#product-carousel {
  position: relative;
  overflow: hidden;
}

.slide {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: none;
}

.slide.active {
  display: block;
  animation: fadeIn 0.5s ease-in-out;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

class Carousel {
  constructor(containerId) {
    this.container = document.getElementById(containerId);
    this.slides = this.container.querySelectorAll('.slide');
    this.currentIndex = 0;
    this.slides[this.currentIndex].classList.add('active');
  }

  next() {
    this._goTo(this.currentIndex + 1);
  }

  previous() {
    this._goTo(this.currentIndex - 1);
  }

  _goTo(index) {
    const total = this.slides.length;
    const newIndex = (index + total) % total;
    this.slides[this.currentIndex].classList.remove('active');
    this.slides[newIndex].classList.add('active');
    this.currentIndex = newIndex;
    this.container.dispatchEvent(new CustomEvent('slideChanged', {
      detail: { index: this.currentIndex }
    }));
  }
}

// Example usage
const carousel = new Carousel('product-carousel');
carousel.next();

CREATE TABLE Categories (
    CategoryID INT PRIMARY KEY,
    CategoryName VARCHAR(100) NOT NULL
);

CREATE TABLE Products (
    ProductID INT PRIMARY KEY,
    ProductName VARCHAR(100) NOT NULL,
    CategoryID INT NOT NULL,
    CONSTRAINT FK_Products_Categories FOREIGN KEY (CategoryID)
        REFERENCES Categories(CategoryID)
        ON DELETE CASCADE
);

INSERT INTO Products (ProductID, ProductName, CategoryID) VALUES (1, 'Sample Widget', 10);
DELETE FROM Categories WHERE CategoryID = 10;
-- Because the foreign key in Products was defined with ON DELETE CASCADE, the product row inserted above is automatically removed when the category is deleted.
